import{_ as p,a0 as t,w as o,s as h,ao as r,I as l,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux Shell 編程中定義和使用函數 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux Shell 編程中定義和使用函數 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux Shell 編程中定義和使用函數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux Shell 編程中定義和使用函數 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180819 How to define and use functions in Linux Shell Script","title":"如何在 Linux Shell 編程中定義和使用函數","tag":"201808","desc":""},"relativePath":"201808/20180819 How to define and use functions in Linux Shell Script.md","filePath":"[post].md"}'),d={name:"201808/20180819 How to define and use functions in Linux Shell Script.md"};function c(g,s,u,k,b,f){const n=t("Link");return o(),h("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-shell-編程中定義和使用函數" tabindex="-1">如何在 Linux Shell 編程中定義和使用函數 <a class="header-anchor" href="#如何在-linux-shell-編程中定義和使用函數" aria-label="Permalink to “如何在 Linux Shell 編程中定義和使用函數”">​</a></h1><p>函數是一段可複用的代碼。我們通常把重複的代碼放進函數中並且在不同的地方去調用它。庫是函數的集合。我們可以在庫中定義經常使用的函數，這樣其它腳本便可以不再重複代碼而使用這些函數。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/08/Functions-Linux-Shell-Script.jpg" alt="Functions-Linux-Shell-Script"></p><p>本文我們將討論諸多關於函數的內容和一些使用技巧。為了方便演示，我將在 Ubuntu 系統上使用 <strong>Bourne Again SHell (Bash)</strong>。</p><h3 id="調用函數" tabindex="-1">調用函數 <a class="header-anchor" href="#調用函數" aria-label="Permalink to “調用函數”">​</a></h3><p>在 Shell 中調用函數和調用其它命令是一模一樣的。例如，如果你的函數名稱為 <code>my_func</code>，你可以在命令列中像下面這樣執行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ my_func</span></span></code></pre></div><p>如果你的函數接收多個參數，那麼可以像下面這樣寫（類似命令列參數的使用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ my_func arg1 arg2 arg3</span></span></code></pre></div><h3 id="定義函數" tabindex="-1">定義函數 <a class="header-anchor" href="#定義函數" aria-label="Permalink to “定義函數”">​</a></h3><p>我們可以用下面的語法去定義一個函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function function_name {</span></span>
<span class="line"><span>    Body of function</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>函數的主體可以包含任何有效的命令、循環語句和其它函數或腳本。現在讓我們創建一個簡單的函數，它向屏幕上顯示一些消息（注：直接在命令列裏寫）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello, World&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在，讓我們執行這個函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ print_msg</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>不出所料，這個函數在屏幕上顯示了一些消息。</p><p>在上面的例子中，我們直接在終端裏創建了一個函數。這個函數也可以保存到文件中。如下面的例子所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello, World&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>print_msg</span></span></code></pre></div><p>我們已經在 <code>function.sh</code> 文件中定義了這個函數。現在讓我們執行這個腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x function.sh</span></span>
<span class="line"><span>$ ./function.sh</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>你可以看到，上面的輸出和之前的是一模一樣的。</p><h3 id="更多函數用法" tabindex="-1">更多函數用法 <a class="header-anchor" href="#更多函數用法" aria-label="Permalink to “更多函數用法”">​</a></h3><p>在上一小節中我們定義了一個非常簡單的函數。然而在軟件開發的過程中，我們需要更多高級的函數，它可以接收多個參數並且帶有返回值。在這一小節中，我們將討論這種函數。</p><h4 id="向函數傳遞參數" tabindex="-1">向函數傳遞參數 <a class="header-anchor" href="#向函數傳遞參數" aria-label="Permalink to “向函數傳遞參數”">​</a></h4><p>我們可以像調用其它命令那樣給函數提供參數。我們可以在函數里使用美元 <code>$</code> 符號訪問到這些參數。例如，<code>$1</code> 表示第一個參數，<code>$2</code> 代表第二個參數，以此類推。</p><p>讓我們修改下之前的函數，讓它以參數的形式接收信息。修改後的函數就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello $1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的函數中我們使用 <code>$1</code> 符號訪問第一個參數。讓我們執行這個函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ print_msg &quot;LinuxTechi&quot;</span></span></code></pre></div><p>執行完後，生成如下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hello LinuxTechi</span></span></code></pre></div><h4 id="從函數中返回數值" tabindex="-1">從函數中返回數值 <a class="header-anchor" href="#從函數中返回數值" aria-label="Permalink to “從函數中返回數值”">​</a></h4><p>跟其它編程語言一樣，Bash 提供了返回語句讓我們可以向調用者返回一些數值。讓我們舉例説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function func_return_value {</span></span>
<span class="line"><span>    return 10</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的函數向調用者返回 <code>10</code>。讓我們執行這個函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ func_return_value</span></span>
<span class="line"><span>$ echo &quot;Value returned by function is: $?&quot;</span></span></code></pre></div><p>當你執行完，將會產生如下的輸出結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Value returned by function is: 10</span></span></code></pre></div><p><strong>提示</strong>：在 Bash 中使用 <code>$?</code> 去獲取函數的返回值。</p><h3 id="函數技巧" tabindex="-1">函數技巧 <a class="header-anchor" href="#函數技巧" aria-label="Permalink to “函數技巧”">​</a></h3><p>目前我們已經對 Bash 中的函數有了一些瞭解。現在讓我們創建一些非常有用的 Bash 函數，它們可以讓我們的生活變得更加輕鬆。</p><h4 id="logger" tabindex="-1">Logger <a class="header-anchor" href="#logger" aria-label="Permalink to “Logger”">​</a></h4><p>讓我們創建一個 <code>logger</code> 函數，它可以輸出帶有日期和時間的 log 信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function log_msg {</span></span>
<span class="line"><span>    echo &quot;[\`date &#39;+ %F %T&#39;\` ]: $@&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>執行這個函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ log_msg &quot;This is sample log message&quot;</span></span></code></pre></div><p>執行完，就會生成如下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ 2018-08-16 19:56:34 ]: This is sample log message</span></span></code></pre></div><h4 id="顯示系統信息" tabindex="-1">顯示系統信息 <a class="header-anchor" href="#顯示系統信息" aria-label="Permalink to “顯示系統信息”">​</a></h4><p>讓我們創建一個顯示 GNU/Linux 信息的函數</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function system_info {</span></span>
<span class="line"><span>    echo &quot;### OS information ###&quot;</span></span>
<span class="line"><span>    lsb_release -a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;### Processor information ###&quot;</span></span>
<span class="line"><span>    processor=\`grep -wc &quot;processor&quot; /proc/cpuinfo\`</span></span>
<span class="line"><span>    model=\`grep -w &quot;model name&quot; /proc/cpuinfo  | awk -F: &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    echo &quot;Processor = $processor&quot;</span></span>
<span class="line"><span>    echo &quot;Model     = $model&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;### Memory information ###&quot;</span></span>
<span class="line"><span>    total=\`grep -w &quot;MemTotal&quot; /proc/meminfo | awk &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    free=\`grep -w &quot;MemFree&quot; /proc/meminfo | awk &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    echo &quot;Total memory: $total kB&quot;</span></span>
<span class="line"><span>    echo &quot;Free memory : $free kB&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>執行完後會生成以下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### OS information ###</span></span>
<span class="line"><span>No LSB modules are available.</span></span>
<span class="line"><span>Distributor ID:           Ubuntu</span></span>
<span class="line"><span>Description:   Ubuntu 18.04.1 LTS</span></span>
<span class="line"><span>Release:         18.04</span></span>
<span class="line"><span>Codename:    bionic</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Processor information ###</span></span>
<span class="line"><span>Processor = 1</span></span>
<span class="line"><span>Model     =  Intel(R) Core(TM) i7-7700HQ CPU @ 2.80GHz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Memory information ###</span></span>
<span class="line"><span>Total memory: 4015648 kB</span></span>
<span class="line"><span>Free memory : 2915428 kB</span></span></code></pre></div><h4 id="在當前目錄下查找文件或者目錄" tabindex="-1">在當前目錄下查找文件或者目錄 <a class="header-anchor" href="#在當前目錄下查找文件或者目錄" aria-label="Permalink to “在當前目錄下查找文件或者目錄”">​</a></h4><p>下面的函數從當前目錄下查找文件或者目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function search {</span></span>
<span class="line"><span>    find . -name $1</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>讓我們使用下面的命令查找 <code>dir4</code> 這個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ search dir4</span></span></code></pre></div><p>當你執行完命令後，將會產生如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./dir1/dir2/dir3/dir4</span></span></code></pre></div><h4 id="數字時鐘" tabindex="-1">數字時鐘 <a class="header-anchor" href="#數字時鐘" aria-label="Permalink to “數字時鐘”">​</a></h4><p>下面的函數在終端裏創建了一個簡單的數字時鐘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function digital_clock {</span></span>
<span class="line"><span>    clear</span></span>
<span class="line"><span>    while [ 1 ]</span></span>
<span class="line"><span>    do</span></span>
<span class="line"><span>        date +&#39;%T&#39;</span></span>
<span class="line"><span>        sleep 1</span></span>
<span class="line"><span>        clear</span></span>
<span class="line"><span>    done</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="函數庫" tabindex="-1">函數庫 <a class="header-anchor" href="#函數庫" aria-label="Permalink to “函數庫”">​</a></h3><p>庫是函數的集合。將函數定義在文件裏並在當前環境中導入那個文件，這樣可以創建函數庫。</p><p>假設我們已經在 <code>utils.sh</code> 中定義好了所有函數，接着在當前的環境下使用下面的命令導入函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source utils.sh</span></span></code></pre></div><p>之後你就可以像調用其它 Bash 命令那樣執行庫中任何的函數了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文我們討論了諸多可以提升效率的實用技巧。我希望這篇文章能夠啓發你去創造自己的技巧。</p><hr>`,72)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/define-use-functions-linux-shell-script/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/define-use-functions-linux-shell-script/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(n,{href:"https://github.com/LuuMing"},{default:e(()=>[...s[4]||(s[4]=[a("LuuMing",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(n,{href:"https://github.com/pityonline"},{default:e(()=>[...s[5]||(s[5]=[a("pityonline",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(d,[["render",c]]);export{x as __pageData,C as default};
